|range        = {{dv|{{tip|cr|icononly = true}} {{tt|950|Gun shot missile range}}|{{tip|cr|icononly = true}} {{tt|400|Cone range strictly forward, cone origin is 200 units behind Samira but can't hit if the unit is closer than 50 units from the cone origin}}}}
|target range = {{tip|er|icononly = true}} {{tt|340|Blade targeting check length}}
|width        = {{dv|{{tip|er|icononly = true}} {{tt|120|Gun shot}}|{{tt|130|Blade targeting check width}}}}
|angle        = {{tt|100|Blade angle}}{{degree}}
